/* =============================================================================
 * malavi.js: the MalAvi site's behavior.
 *
 * Split out of the original single-file design preview. Every figure the page
 * shows is read from assets/data/site_stats.json, which is generated by
 * export/build_site_stats.R from the pinned malaviR release. No count is
 * written into the markup or into this file: bump the release, re-run the
 * export, and the site follows.
 *
 * Loaded as a module, so it is deferred until the DOM is parsed and can use
 * top-level await to fetch its data before rendering.
 * ============================================================================= */

const [STATS, DATA, MAP, REPORTS] = await Promise.all([
  fetch("assets/data/site_stats.json").then((r) => r.json()),
  fetch("assets/data/tables_preview.json").then((r) => r.json()),
  fetch("assets/data/world_map.json").then((r) => r.json()),
  fetch("assets/data/reports.json").then((r) => r.json())
]);
(function () {
  "use strict";

  /* STATS is the verbatim output of export/build_site_stats.R, which derives every
     figure below from the pinned malaviR release. Nothing on this page is typed in:
     bump the release, re-run the generator, and the whole site follows.
     DATA carries the table rows; MAP carries the fixed basemap shapes and the
     MalAvi-name -> basemap-name aliases. */

  /* ------------------------------------------------------------------ theme */
  var root = document.documentElement;
  var themeBtn = document.getElementById("themeBtn");
  function prefersDark() {
    return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
  }
  function currentlyDark() {
    var set = root.getAttribute("data-theme");
    return set ? set === "dark" : prefersDark();
  }
  themeBtn.addEventListener("click", function () {
    root.setAttribute("data-theme", currentlyDark() ? "light" : "dark");
    themeBtn.textContent = currentlyDark() ? "Light" : "Dark";
  });
  themeBtn.textContent = currentlyDark() ? "Light" : "Dark";

  /* ------------------------------------------------------------- navigation */
  function show(name) {
    Array.prototype.forEach.call(document.querySelectorAll("#nav button"), function (b) {
      if (b.dataset.view === name) b.setAttribute("aria-current", "page");
      else b.removeAttribute("aria-current");
    });
    Array.prototype.forEach.call(document.querySelectorAll(".view"), function (v) {
      v.classList.toggle("active", v.id === "view-" + name);
    });
    window.scrollTo({ top: 0, behavior: "instant" });
  }
  document.getElementById("nav").addEventListener("click", function (e) {
    var b = e.target.closest("button[data-view]");
    if (b) show(b.dataset.view);
  });
  document.getElementById("brandHome").addEventListener("click", function () { show("home"); });
  document.addEventListener("click", function (e) {
    var g = e.target.closest("[data-goto]");
    if (g) { e.preventDefault(); show(g.dataset.goto); return; }
    var el = e.target.closest("[data-goto-el]");
    if (el) {
      e.preventDefault();
      document.getElementById(el.dataset.gotoEl)
        .scrollIntoView({ behavior: "smooth", block: "start" });
    }
  });

  /* --------------------------------------------------------------- home viz */

  /* Presentation only: the fixed display order and the color slot each genus
     owns. Every VALUE comes from STATS. Genus order is itself carried in the
     payload, so the colors follow the data rather than a list kept in sync by
     hand. */
  var SLOT = {
    Plasmodium:    { varName: "--g-p", ramp: "p", cls: "sw-p" },
    Haemoproteus:  { varName: "--g-h", ramp: "h", cls: "sw-h" },
    Leucocytozoon: { varName: "--g-l", ramp: "l", cls: "sw-l" }
  };
  var GENERA = STATS.genera.map(function (g) {
    var slot = SLOT[g.key] || { varName: "--ink-3", ramp: "p", cls: "" };
    return {
      key: g.key, varName: slot.varName, ramp: slot.ramp, cls: slot.cls,
      lineages: g.lineages, records: g.records,
      host_species: g.host_species, host_genera: g.host_genera,
      host_families: g.host_families, host_orders: g.host_orders
    };
  });
  var TOTAL_LINEAGES = STATS.totals.lineages;

  function n(value) { return Number(value).toLocaleString(); }

  /* Fill every element that binds to a single figure. */
  function bindStats(mapped, unplaced) {
    var values = {
      release:   STATS.release,
      countries: n(STATS.totals.countries),
      unassigned: n(STATS.unassigned_lineages),
      alnlen:    n(STATS.alignment_length_bp),
      mapped:    n(mapped),
      unplaced:  n(unplaced)
    };
    Array.prototype.forEach.call(document.querySelectorAll("[data-stat]"), function (el) {
      var v = values[el.dataset.stat];
      if (v != null) el.textContent = v;
    });
  }

  /* The headline strip. Labels are presentation; every number is from STATS. */
  var STRIP = [
    ["lineages", "Lineages"], ["host_records", "Host records"],
    ["host_species", "Host species"], ["host_genera", "Host genera"],
    ["host_families", "Host families"], ["host_orders", "Host orders"],
    ["countries", "Countries"], ["references", "References"]
  ];
  function drawStrip() {
    document.getElementById("statStrip").innerHTML = STRIP.map(function (pair) {
      return '<div class="stat"><div class="n display">' + n(STATS.totals[pair[0]]) +
             '</div><div class="k">' + pair[1] + "</div></div>";
    }).join("");
  }

  /* Composition bar + its legend, from the per-genus record counts. */
  function drawComposition() {
    var total = GENERA.reduce(function (s, g) { return s + g.records; }, 0);
    document.getElementById("genusBar").setAttribute("aria-label",
      GENERA.map(function (g) { return g.key + " " + n(g.records) + " records"; }).join("; "));
    document.getElementById("genusBar").innerHTML = GENERA.map(function (g) {
      return '<span style="flex:' + g.records + ';background:var(' + g.varName + ')"></span>';
    }).join("");
    document.getElementById("genusLegend").innerHTML = GENERA.map(function (g) {
      return '<span><i style="background:var(' + g.varName + ')"></i><em class="sci">' +
             g.key + '</em> <span class="mono">' + n(g.records) + "</span> (" +
             Math.round(g.records / total * 100) + "%)</span>";
    }).join("");
    document.getElementById("rankLegend").innerHTML = GENERA.map(function (g) {
      return '<span><i style="background:var(' + g.varName + ')"></i><em class="sci">' +
             g.key + "</em></span>";
    }).join("");
  }

  /* Three dials, each one genus as a share of all lineages. The count is the
     hero; the ring is secondary. Part-to-whole, so a ring is honest here --
     unlike the taxonomic ranks below, where the sets overlap. */
  function drawDonuts() {
    var host = document.getElementById("donuts");
    host.innerHTML = GENERA.map(function (g) {
      var r = 42, c = 2 * Math.PI * r;
      var share = g.lineages / TOTAL_LINEAGES;
      return '<div class="donut">' +
        '<svg width="112" height="112" viewBox="0 0 112 112" role="img" aria-label="' +
          g.key + ": " + g.lineages + " lineages, " + Math.round(share * 100) + '% of all lineages">' +
          '<circle cx="56" cy="56" r="' + r + '" fill="none" stroke="var(--surface-3)" stroke-width="13"/>' +
          '<circle cx="56" cy="56" r="' + r + '" fill="none" stroke="var(' + g.varName + ')" ' +
            'stroke-width="13" stroke-linecap="butt" stroke-dasharray="' +
            (c * share).toFixed(1) + " " + c.toFixed(1) + '" transform="rotate(-90 56 56)"/>' +
        "</svg>" +
        '<div class="val display">' + g.lineages.toLocaleString() + "</div>" +
        '<div class="lab sci">' + g.key + "</div>" +
        '<div class="sub">' + Math.round(share * 100) + "% of all lineages</div>" +
      "</div>";
    }).join("");
  }

  /* Host taxa reached, per parasite genus. The sets overlap -- a host species can
     carry more than one genus -- so these are bars, not rings: they show reach,
     not shares. Values are read straight off the per-genus payload. */
  var RANKS = [
    { field: "host_species",  label: "Host species" },
    { field: "host_genera",   label: "Host genera" },
    { field: "host_families", label: "Host families" },
    { field: "host_orders",   label: "Host orders" }
  ];
  function drawRanks() {
    document.getElementById("ranks").innerHTML = RANKS.map(function (rank) {
      var max = Math.max.apply(null, GENERA.map(function (g) { return g[rank.field]; }));
      var bars = GENERA.map(function (g) {
        var v = g[rank.field];
        return '<div class="rbar">' +
          '<div class="glab"><span class="sci">' + g.key + '</span>' +
            '<span class="v">' + n(v) + "</span></div>" +
          '<div class="track"><span class="fill" style="width:' + (v / max * 100).toFixed(1) +
            '%;background:var(' + g.varName + ')"></span></div>' +
        "</div>";
      }).join("");
      return '<div class="rank-card"><h4>' + rank.label + "</h4>" +
             '<div class="rank-bars">' + bars + "</div></div>";
    }).join("");
  }

  /* Choropleths: one panel per genus, one hue light-to-dark within each. */
  var BINS = [
    { min: 1,  max: 2,   step: 1 },
    { min: 3,  max: 5,   step: 2 },
    { min: 6,  max: 10,  step: 3 },
    { min: 11, max: 25,  step: 4 },
    { min: 26, max: 1e9, step: 5 }
  ];
  function binFor(n) {
    for (var i = 0; i < BINS.length; i++) if (n >= BINS[i].min && n <= BINS[i].max) return BINS[i].step;
    return 0;
  }
  /* Join the release's per-country counts onto the fixed basemap. The counts are
     keyed by MalAvi's own country spelling; MAP.aliases translates the handful
     that the basemap names differently. Anything that will not join is reported
     by the generator, so a new country in a future release surfaces rather than
     quietly disappearing from the map. */
  function joinCountsToBasemap() {
    var byAtlasName = {};
    var placed = 0, unplaced = 0;
    Object.keys(STATS.country_studies).forEach(function (malaviName) {
      var atlasName = MAP.aliases[malaviName] || malaviName;
      if (MAP.paths[atlasName]) {
        byAtlasName[atlasName] = STATS.country_studies[malaviName];
        placed++;
      } else {
        unplaced++;
      }
    });
    return { counts: byAtlasName, placed: placed, unplaced: unplaced };
  }

  var JOINED = joinCountsToBasemap();

  function drawMaps() {
    document.getElementById("maps").innerHTML = GENERA.map(function (g) {
      var initial = g.key.charAt(0);
      var shaded = 0;
      var paths = Object.keys(MAP.paths).map(function (name) {
        var count = (JOINED.counts[name] || {})[initial] || 0;
        if (count) shaded++;
        var fill = count ? "var(--" + g.ramp + binFor(count) + ")" : "var(--map-none)";
        return '<path d="' + MAP.paths[name] + '" fill="' + fill +
               '" data-country="' + name + '" data-n="' + count + '"></path>';
      }).join("");
      var swatches = [1, 2, 3, 4, 5].map(function (s) {
        return '<i style="background:var(--' + g.ramp + s + ')"></i>';
      }).join("");
      return '<div class="map-panel" data-genus="' + g.key + '">' +
        '<h4 class="sci">' + g.key + "</h4>" +
        '<p class="cap">' + shaded + " countries with records</p>" +
        '<svg viewBox="0 0 ' + MAP.width + " " + MAP.height + '" role="img" aria-label="' +
          g.key + ' studies per country">' + paths + "</svg>" +
        '<div class="scale"><span>1</span>' + swatches + "<span>26+ studies</span></div>" +
        '<div class="map-tip">Hover a country</div>' +
      "</div>";
    }).join("");

    /* Hover readout, per panel. */
    document.getElementById("maps").addEventListener("mouseover", function (e) {
      var p = e.target.closest("path[data-country]");
      if (!p) return;
      var panel = p.closest(".map-panel");
      var n = Number(p.dataset.n);
      panel.querySelector(".map-tip").textContent = n
        ? p.dataset.country + ": " + n + " stud" + (n === 1 ? "y" : "ies")
        : p.dataset.country + ": no records";
    });
    document.getElementById("maps").addEventListener("mouseout", function (e) {
      var panel = e.target.closest(".map-panel");
      if (panel && !panel.contains(e.relatedTarget)) {
        panel.querySelector(".map-tip").textContent = "Hover a country";
      }
    });
  }

  bindStats(JOINED.placed, JOINED.unplaced);
  drawStrip(); drawComposition(); drawDonuts(); drawRanks(); drawMaps();

  /* ----------------------------------------------------------- tables index */
  var GENUS_CLASS = { Plasmodium: "sw-p", Haemoproteus: "sw-h", Leucocytozoon: "sw-l" };

  function escapeHtml(v) {
    return String(v == null ? "" : v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  /* The table list is driven by STATS.tables -- title, description and row count
     all come from the release. DATA supplies only the column spec and the sample
     rows this preview renders; in the live site those come from the exported
     per-table JSON. */
  var TABLES = STATS.tables.map(function (meta) {
    var payload = DATA.tables[meta.id] || { columns: [], rows: [] };
    return {
      id: meta.id, title: meta.title, description: meta.description,
      totalRows: meta.rows, columns: payload.columns, rows: payload.rows
    };
  }).filter(function (t) { return t.columns.length; });

  document.getElementById("tindex").innerHTML = TABLES.map(function (t) {
    return '<div class="tindex-row">' +
      '<div class="tindex-main"><a data-open="' + t.id + '">' + escapeHtml(t.title) + "</a>" +
        "<p>" + escapeHtml(t.description) + "</p></div>" +
      '<span class="rowcount">' + n(t.totalRows) + " rows</span>" +
      '<div class="tindex-actions">' +
        '<button class="mini" data-open="' + t.id + '">Open</button>' +
        '<a class="mini" href="#">CSV</a><a class="mini" href="#">Excel</a>' +
      "</div></div>";
  }).join("");

  /* ------------------------------------------------- downloads and reports */
  /* Every generated file is named <stem>_<release>.<ext>, so the release string
     is the only thing needed to build a link. Nothing here is hard-coded: bump
     the release, re-run the export scripts, and the links follow. */
  var RELEASE = STATS.release;

  var alignmentLink = document.getElementById("dlAlignment");
  if (alignmentLink) {
    alignmentLink.href = "assets/downloads/malavi_alignment_" + RELEASE + ".fasta";
  }
  var everythingLink = document.getElementById("dlEverything");
  if (everythingLink) {
    everythingLink.href = "assets/downloads/malavi_" + RELEASE + ".zip";
  }

  /* The report cards are rendered from reports.json, written by
     export/build_reports.R alongside the CSVs it generates, so the row counts
     shown here cannot drift from the files they describe. */
  Array.prototype.forEach.call(document.querySelectorAll("[data-reports]"), function (host) {
    host.innerHTML = REPORTS.reports.map(function (r) {
      return '<a href="assets/reports/' + encodeURIComponent(r.file) + '" download>' +
             '<span class="nm">' + escapeHtml(r.title) + "</span>" +
             '<span class="ds">' + escapeHtml(r.description) + "</span>" +
             '<span class="fm">CSV · ' + n(r.rows) + " rows</span></a>";
    }).join("");
  });

  /* ------------------------------------------------------------ table view */
  var state = { table: null, page: 0, size: 25, filters: {} };
  var indexEl = document.getElementById("tablesIndex");
  var viewEl = document.getElementById("tableView");

  function openTable(id) {
    state.table = TABLES.filter(function (t) { return t.id === id; })[0];
    if (!state.table) return;
    state.page = 0;
    state.filters = {};
    document.getElementById("tvTitle").textContent = state.table.title;
    document.getElementById("tvDesc").textContent = state.table.description;
    document.getElementById("tvNote").textContent =
      "Showing " + n(state.table.rows.length) + " sample rows of " +
      n(state.table.totalRows) + " for this preview. The live table carries all of them.";
    /* Point the two download buttons at this table's generated files. The page
       only holds a preview, so these must serve the complete table, not what is
       currently filtered on screen. */
    var stem = "assets/downloads/tables/" + state.table.id + "_" + RELEASE;
    document.getElementById("dlCsv").href = stem + ".csv";
    document.getElementById("dlXlsx").href = stem + ".xlsx";
    buildHead();
    render();
    indexEl.style.display = "none";
    viewEl.style.display = "";
    window.scrollTo({ top: 0, behavior: "instant" });
  }

  function buildHead() {
    var cols = state.table.columns;
    document.getElementById("tvHead").innerHTML =
      "<tr>" + cols.map(function (c) { return "<th>" + escapeHtml(c.label) + "</th>"; }).join("") + "</tr>" +
      '<tr class="colfilters">' + cols.map(function (c) {
        return '<th><input type="search" data-col="' + c.key +
               '" placeholder="filter" aria-label="Filter by ' + escapeHtml(c.label) + '"></th>';
      }).join("") + "</tr>";
  }

  function filteredRows() {
    var active = Object.keys(state.filters).filter(function (k) { return state.filters[k]; });
    if (!active.length) return state.table.rows;
    return state.table.rows.filter(function (row) {
      return active.every(function (key) {
        return String(row[key] == null ? "" : row[key]).toLowerCase()
          .indexOf(state.filters[key]) !== -1;
      });
    });
  }

  function cellHtml(col, row) {
    var v = row[col.key];
    if (col.type === "genus") {
      return '<td><span class="genus-pill"><i class="' + (GENUS_CLASS[v] || "") + '"></i>' +
             escapeHtml(v) + "</span></td>";
    }
    var cls = col.type === "key" ? "key" : col.type === "num" ? "num"
            : col.type === "wrap" ? "wrap" : col.type === "sci" ? "sci" : "";
    return "<td" + (cls ? ' class="' + cls + '"' : "") + ">" + escapeHtml(v) + "</td>";
  }

  function pagerHtml(totalPages) {
    return '<button class="pgFirst" ' + (state.page === 0 ? "disabled" : "") + ">First</button>" +
           '<button class="pgPrev" '  + (state.page === 0 ? "disabled" : "") + ">Prev</button>" +
           '<span class="pos">Page ' + (state.page + 1) + " of " + Math.max(totalPages, 1) + "</span>" +
           '<button class="pgNext" ' + (state.page >= totalPages - 1 ? "disabled" : "") + ">Next</button>" +
           '<button class="pgLast" ' + (state.page >= totalPages - 1 ? "disabled" : "") + ">Last</button>";
  }

  function render() {
    var cols = state.table.columns;
    var rows = filteredRows();
    var totalPages = Math.ceil(rows.length / state.size) || 1;
    if (state.page > totalPages - 1) state.page = totalPages - 1;
    var start = state.page * state.size;
    var slice = rows.slice(start, start + state.size);

    document.getElementById("tvBody").innerHTML = slice.length
      ? slice.map(function (row) {
          return "<tr>" + cols.map(function (c) { return cellHtml(c, row); }).join("") + "</tr>";
        }).join("")
      : '<tr><td class="empty" colspan="' + cols.length +
        '">No rows match those filters. Clear one to widen the search.</td></tr>';

    document.getElementById("tvCount").textContent =
      rows.length.toLocaleString() + " matching row" + (rows.length === 1 ? "" : "s") +
      (slice.length ? " · showing " + (start + 1) + "–" + (start + slice.length) : "");

    document.getElementById("pagerTop").innerHTML = pagerHtml(totalPages);
    document.getElementById("pagerBottom").innerHTML = pagerHtml(totalPages);
  }

  document.addEventListener("click", function (e) {
    var open = e.target.closest("[data-open]");
    if (open) { e.preventDefault(); openTable(open.dataset.open); return; }

    var page = e.target.closest(".pager button");
    if (page && state.table) {
      var totalPages = Math.ceil(filteredRows().length / state.size) || 1;
      if (page.classList.contains("pgFirst")) state.page = 0;
      else if (page.classList.contains("pgPrev")) state.page = Math.max(0, state.page - 1);
      else if (page.classList.contains("pgNext")) state.page = Math.min(totalPages - 1, state.page + 1);
      else if (page.classList.contains("pgLast")) state.page = totalPages - 1;
      render();
    }
  });

  document.getElementById("backToIndex").addEventListener("click", function () {
    viewEl.style.display = "none";
    indexEl.style.display = "";
    window.scrollTo({ top: 0, behavior: "instant" });
  });

  document.getElementById("pageSize").addEventListener("change", function (e) {
    state.size = Number(e.target.value);
    state.page = 0;
    render();
  });

  document.getElementById("tvHead").addEventListener("input", function (e) {
    var input = e.target.closest("input[data-col]");
    if (!input) return;
    state.filters[input.dataset.col] = input.value.trim().toLowerCase();
    state.page = 0;
    render();
  });

  document.getElementById("clearFilters").addEventListener("click", function () {
    state.filters = {};
    Array.prototype.forEach.call(
      document.querySelectorAll("#tvHead input"), function (i) { i.value = ""; });
    state.page = 0;
    render();
  });

  /* --------------------------------------------------------- the checker
     The matching logic lives in sequence-check.mjs, which is tested against
     every sequence in the release (assets/js/tests/test_sequence_check.mjs).
     Nothing about identity is decided in this file.

     The reference index is ~3 MB uncompressed (about 200 KB over the wire) and
     is only needed by people who actually use the checker, so it is fetched on
     first use rather than on page load. */
  let checkerPromise = null;

  function loadChecker() {
    if (!checkerPromise) {
      checkerPromise = Promise.all([
        import("./sequence-check.mjs"),
        fetch("assets/data/lineage_sequences.json").then(function (r) {
          if (!r.ok) throw new Error("could not load the lineage index");
          return r.json();
        })
      ]).then(function (parts) {
        var module = parts[0];
        return { module: module, index: module.buildIndex(parts[1]) };
      });
    }
    return checkerPromise;
  }

  var MARKS = { known: "\u2713", "new": "\u25c6", stop: "\u2715", unknown: "\u25c6" };

  function renderResult(outId, result) {
    var box = document.getElementById(outId);
    var checks = (result.checks || []).map(function (c) {
      return '<li><span class="tag t-' + c.state + '">' + c.label + "</span><span>" +
             c.text + "</span></li>";
    });
    var html = '<div class="verdict v-' + result.verdict + '"><span class="mark">' +
      (MARKS[result.verdict] || "") + '</span><div><h4>' + result.title + "</h4><p>" +
      result.message + "</p></div></div>";
    if (checks.length) html += '<ul class="checklist">' + checks.join("") + "</ul>";
    box.innerHTML = html;
    box.classList.add("show");
  }

  function renderMessage(outId, verdict, title, message) {
    renderResult(outId, { verdict: verdict, title: title, message: message, checks: [] });
  }

  document.addEventListener("click", function (e) {
    var runner = e.target.closest("[data-check]");
    if (runner) {
      var raw = document.getElementById(runner.dataset.check).value;
      var out = runner.dataset.out;
      renderMessage(out, "unknown", "Checking\u2026",
        "Loading the lineage index. This happens once per visit.");
      loadChecker().then(function (checker) {
        renderResult(out, checker.module.checkSequence(checker.index, raw));
      }).catch(function (err) {
        renderMessage(out, "stop", "Could not run the checks",
          "The lineage index did not load (" + err.message + "). Please reload the page, " +
          "or send us the sequence and we will check it for you.");
      });
      return;
    }

    var demo = e.target.closest("[data-demo]");
    if (demo) {
      /* A real lineage sequence with two point changes, so the example lands on
         the interesting answer: a plausible new lineage. Taken from the loaded
         index so it is always a genuine sequence from the current release. */
      var target = document.getElementById(demo.dataset.demo);
      target.value = "Loading an example\u2026";
      loadChecker().then(function (checker) {
        var entry = checker.index.entries.find(function (x) {
          return x.ungapped.length === checker.index.windowLength;
        }) || checker.index.entries[0];
        var seed = entry.ungapped;
        seed = seed.slice(0, 120) + (seed[120] === "A" ? "G" : "A") +
               seed.slice(121, 300) + (seed[300] === "T" ? "C" : "T") + seed.slice(301);
        target.value = (seed.match(/.{1,60}/g) || []).join("\n");
      }).catch(function () {
        target.value = "";
      });
    }
  });
})();
